function validate(input) {
  const [{ Transactions = [] }] = input;
  const keys = new Set(), byAccount = new Map();
  for (const row of Transactions) {
    const [account, day, type, amount] = row;
    if (account === null) return 'Every transaction needs an account_id.';
    if (typeof day !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(day)) return `Account ${account} needs a YYYY-MM-DD day.`;
    const key = `${account}/${day}`;
    if (keys.has(key)) return `Account ${account} has two transactions on ${day}.`;
    keys.add(key);
    if (type !== 'Deposit' && type !== 'Withdraw') return `type must be 'Deposit' or 'Withdraw', not ${type}.`;
    if (amount === null || amount < 0) return `Account ${account} on ${day} needs a non-negative amount.`;
    if (!byAccount.has(account)) byAccount.set(account, []);
    byAccount.get(account).push(row);
  }
  for (const [account, rows] of byAccount) {
    let balance = 0;
    for (const [, day, type, amount] of rows.sort((a, b) => (a[1] < b[1] ? -1 : 1))) {
      balance += type === 'Deposit' ? amount : -amount;
      if (balance < 0) return `Account ${account} goes below 0 on ${day}.`;
    }
  }
  return null;
}

