function generate(rand, size) {
  const small = size === 'small';
  const day = offset => new Date(Date.UTC(2021, 10, 1) + offset * 86400000).toISOString().slice(0, 10);
  const Transactions = [];
  const accounts = small ? 1 + Math.floor(rand() * 3) : 40;
  const perAccount = small ? 3 : 50;
  const amounts = [500, 1000, 2000, 3000, 7000];
  for (let a = 0; a < accounts; a++) {
    const account = small ? [1, 2, 3, 7][a] : a + 1;
    // Distinct days per account, in increasing order; the rows are shuffled afterwards.
    let offset = Math.floor(rand() * 5), balance = 0;
    const n = small ? Math.floor(rand() * (perAccount + 1)) : perAccount;
    for (let i = 0; i < n; i++) {
      let type = rand() < 0.45 && balance > 0 ? 'Withdraw' : 'Deposit';
      let amount = small ? amounts[Math.floor(rand() * amounts.length)] : 100 * (1 + Math.floor(rand() * 100));
      if (type === 'Withdraw') {
        // Withdraw at most the current balance; sometimes exactly all of it.
        amount = rand() < 0.3 ? balance : Math.min(amount, balance);
        balance -= amount;
      } else balance += amount;
      Transactions.push([account, day(offset), type, amount]);
      offset += 1 + Math.floor(rand() * 6);
    }
  }
  for (let i = Transactions.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [Transactions[i], Transactions[j]] = [Transactions[j], Transactions[i]]; }
  return [{ Transactions }];
}
